ALTER TABLE "venture_market" ADD CONSTRAINT "venture_market_factors_check" CHECK ("venture_market"."factors" is null or coalesce(jsonb_typeof("venture_market"."factors") = 'object' and "venture_market"."factors" - array['demand', 'timing', 'competition', 'capital', 'regulatory']::text[] = '{}'::jsonb and jsonb_typeof("venture_market"."factors"->'demand') = 'number' and ("venture_market"."factors"->>'demand') ~ '^[0-9]{1,3}$' and ("venture_market"."factors"->>'demand')::int <= 100 and jsonb_typeof("venture_market"."factors"->'timing') = 'number' and ("venture_market"."factors"->>'timing') ~ '^[0-9]{1,3}$' and ("venture_market"."factors"->>'timing')::int <= 100 and jsonb_typeof("venture_market"."factors"->'competition') = 'number' and ("venture_market"."factors"->>'competition') ~ '^[0-9]{1,3}$' and ("venture_market"."factors"->>'competition')::int <= 100 and jsonb_typeof("venture_market"."factors"->'capital') = 'number' and ("venture_market"."factors"->>'capital') ~ '^[0-9]{1,3}$' and ("venture_market"."factors"->>'capital')::int <= 100 and jsonb_typeof("venture_market"."factors"->'regulatory') = 'number' and ("venture_market"."factors"->>'regulatory') ~ '^[0-9]{1,3}$' and ("venture_market"."factors"->>'regulatory')::int <= 100, false));--> statement-breakpoint
ALTER TABLE "venture_market" ADD CONSTRAINT "venture_market_related_articles_check" CHECK ("venture_market"."related_articles" >= 0);--> statement-breakpoint
ALTER TABLE "venture_progress" ADD CONSTRAINT "venture_progress_counts_check" CHECK ("venture_progress"."sprint_delivered" >= 0 and "venture_progress"."sprint_next" >= 0 and "venture_progress"."tickets_in_qa" >= 0);